# Generated by `roundhouse --target futamura`. Do not edit: rerun the
# transpile instead.
#
# Query chains that Roundhouse found to be static, hoisted out of the
# request. Each `define` holds a chain's Relation with a bind placeholder
# for every value only known at request time. The first request on a
# connection kind builds it once, in Rails, so the SQL, the preload trees
# and the strict-loading setting are all Rails' own. Rails compiles it into
# an ActiveRecord::StatementCache, the mechanism behind `find_by`; each
# request only executes it, then does what Relation#load would have done
# next: mark association records the way AssociationRelation does, preload
# (see Futamura::Preload), and reverse a `last(n)`.
#
# The call site keeps the original chain as a block. It runs instead
# whenever a request-time value is one StatementCache refuses (nil, an
# Array, a Range, a record...), or when the built Relation turns out to need
# something a StatementCache cannot do (eager loading). With
# FUTAMURA_VERIFY=1 it runs as well, to check that both give the same
# records in the same order, with the same associations loaded.
module Futamura
  Statement = Struct.new(:model, :build, :reverse, :one, :unscoped, :owner_keys, :owner_columns, :relation, :via, keyword_init: true)
  Compiled = Struct.new(:cache, :preload, :strict_loading, keyword_init: true)

  # What a model's default scopes add to a query, as the columns each
  # compares for equality, the values it compared them to, and the modules
  # they extend the relation with (`extending`).
  NO_DEFAULTS = [[].freeze, [].freeze, [].freeze].freeze
  # A model whose default scopes are this many times in a row not that
  # simple is left to Rails' chain without evaluating them first, except for
  # one call in OPAQUE_RETRY: a default scope that reads request state may be
  # simple again later.
  OPAQUE_LIMIT = 5
  OPAQUE_RETRY = 64
  # Relation methods that load records. A module a default scope extends the
  # relation with may override a link of the chain (the chain then runs it
  # once, while the statement is built: see `compile`), but not these, which
  # the statement replaces on every call.
  LOADING = %i[load reload records to_a to_ary exec_queries exec_main_query instantiate_records
               preload_associations skip_query_cache_if_necessary first last take find_by find_nth
               find_nth_with_limit find_last ordered_relation arel build_arel klass model
               scope_for_association strict_loading!].freeze

  @statements = {}
  @compiled = Concurrent::Map.new
  @opaque = Concurrent::Map.new
  @extensions = Concurrent::Map.new
  @owner_chains = Concurrent::Map.new
  VERIFY = ENV["FUTAMURA_VERIFY"] == "1"

  class << self
    # `reverse:` for `last(n)`, whose rows Rails loads newest first and
    # reverses; `one:` for `first`/`last`/`take`/`find_by`, which return
    # the first loaded record or nil; `unscoped:` for a chain rooted at
    # `Model.unscoped`, which has no default scopes. `model` is a class or
    # the name of one, resolved at the first call. A chain rooted at an
    # association reader names the key columns the reader compares to the
    # owner (`owner_keys`, checked against the reflection) and every column
    # the association constrains (`owner_columns`). `relation:` says links
    # follow the reader (`notes.where(...).first`): Rails then builds a
    # Relation from `scope` and queries, where a terminal called on the reader
    # itself (`notes.first`) answers from the association's target.
    def define(key, model, reverse: false, one: false, unscoped: false, owner_keys: nil, owner_columns: [], relation: false, via: nil, &build)
      @statements[key] = Statement.new(model: model, build: build, reverse: reverse, one: one, unscoped: unscoped,
                                       owner_keys: owner_keys, owner_columns: owner_columns, relation: relation, via: via)
    end

    # Whether a method the chain calls on `target` (a class, or a record for an association
    # reader) is something other than ActiveRecord's own. A method is Rails' when the code
    # that defines it is in the ActiveRecord gem (`where`, `unscoped`, `find_by`, a generated
    # scope or reader...). One defined by an app class, by a module it extends the class
    # with (a model overriding `unscoped`), by an anonymous module (a test double prepends
    # one) or by a double on the singleton class is the app's: it may read request state or
    # return something else on every call, so the statement, built once from the chain as
    # written, may not stand for it.
    def redefined?(target, name)
      !rails_method?(target.method(name))
    rescue NameError
      true
    end
    private :redefined?

    def rails_method?(method)
      owner = method.owner
      return false if owner.name.nil? && !owner.singleton_class?

      location = method.source_location&.first
      !location.nil? && (location.start_with?(rails_dir) || in_rails_dir?(location))
    end
    private :rails_method?

    # The same files reached through another path (a gem home whose entries are symlinks, as
    # in a Nix store: the methods' source_location and the gem's own differ by prefix only).
    def in_rails_dir?(location)
      @rails_locations ||= {}
      return @rails_locations[location] if @rails_locations.key?(location)

      @rails_locations[location] = begin
        (@rails_real_dir ||= "#{File.realpath(rails_dir)}/")
        File.realpath(location).start_with?(@rails_real_dir)
      rescue SystemCallError
        false
      end
    end
    private :in_rails_dir?

    # The first of `names` (a Symbol or a list of them) that `model` redefines, or nil.
    def redefined_class_method(model, names)
      Array(names).find { |name| redefined?(model, name) }
    end
    private :redefined_class_method

    # Rails starts an association's scope from `klass.unscoped` and `klass.scope_for_association`
    # (AssociationScope, Association#target_scope, Preloader::Association): a class that
    # redefines either has its own conditions in every association read, which a statement
    # built from the class's plain relation does not have.
    def scope_redefined?(klass)
      %i[unscoped scope_for_association].any? { |name| redefined?(klass, name) }
    end
    private :scope_redefined?

    def rails_dir
      @rails_dir ||= "#{File.dirname(ActiveRecord.method(:gem_version).source_location.first)}/"
    end
    private :rails_dir

    # The key `where(association: value)` binds, as Rails'
    # PredicateBuilder::AssociationQueryValue#convert_to_id reads it: the
    # record's primary key column, or the value itself when it has none. A
    # StatementCache takes no record, so the call site passes this instead.
    # nil (which it refuses, so Rails' own chain runs) for an association
    # whose condition is not one key column.
    def association_key(model, name, value)
      reflection = model._reflect_on_association(name)
      return unless reflection&.belongs_to? && !reflection.polymorphic?

      # Where Rails has query constraints (`belongs_to ..., query_constraints:`), the predicate
      # builder reads `query_primary_key` / `query_foreign_key` (AssociationQueryValue), which are
      # composite when the join keys (`join_primary_key` / `join_foreign_key`) are one column.
      primary_key = reflection.respond_to?(:query_primary_key) ? reflection.query_primary_key : reflection.join_primary_key
      foreign_key = reflection.respond_to?(:query_foreign_key) ? reflection.query_foreign_key : reflection.join_foreign_key
      return if primary_key.is_a?(Array) || foreign_key.is_a?(Array)

      value.respond_to?(primary_key) ? value.public_send(primary_key) : value
    end

    # What `Model.find_by(column: value)` reads from a value that responds to
    # `id` (core.rb `find_by`: `value = value.id if value.respond_to?(:id)`, for a
    # key that is not an association) before it builds the statement; the call
    # site passes this for a `find_by` written on the class itself.
    def find_by_value(value)
      value.respond_to?(:id) ? value.id : value
    end

    # Whether a request-time value cannot be one placeholder of a StatementCache: anything but a
    # scalar Rails quotes as a single value. The predicate builder turns an Array, a Set, a Range,
    # a Relation, a Hash or a record into an IN list, BETWEEN, a subquery, nested conditions or
    # a key (PredicateBuilder handlers), and a StatementCache's own check
    # (`StatementCache.unsupported_value?`) names only some of them, so the scalars are listed
    # instead. nil is `IS NULL`. A value of any other class is Rails' to bind.
    def unsupported_bind?(value)
      case value
      when Integer, String, Symbol, Float, BigDecimal, true, false, Date, Time, ActiveSupport::TimeWithZone then false
      else true
      end
    end

    # `root:` is the `self` of a chain written against an implicit class
    # self: the statement is the model's own, so any other class (a subclass
    # adds its type condition, a concern's method is shared) runs the chain.
    def records(key, binds, owner: nil, association: nil, root: nil, &fallback)
      # An owner that is not a record (a test double) is asked nothing: not by a guard, and not by
      # the bind expressions, which a site rooted at an association reader passes as a lambda for
      # that reason (the chain as written does not read the owner's key).
      return fallback.call if owner && !(ActiveRecord::Base === owner)

      binds = binds.call if Proc === binds
      return fallback.call if binds.any? { |value| unsupported_bind?(value) }

      statement = @statements.fetch(key)
      # Named by a String so that defining a statement loads no model: a class
      # body may need run-time state (I18n) a `to_prepare` hook runs too early for.
      model = statement.model
      model = statement.model = Object.const_get(model) if model.is_a?(String)
      return fallback.call if root && !root.equal?(model)
      return fallback.call if statement.via && redefined_class_method(model, statement.via)
      return fallback.call if owner && !owner_chain?(owner, association, statement, model)

      # A `Model.scoping { }` block is part of every `Model.all` inside it.
      return fallback.call if !statement.unscoped && model.current_scope

      columns, defaults, extensions = statement.unscoped ? NO_DEFAULTS : default_binds(model)
      return fallback.call unless columns
      # Merging the association's relation into the model's default scope
      # (Association#scope) replaces a default equality condition on a column
      # the association constrains; the chain built here keeps both.
      return fallback.call if owner && (columns.map { |column| Array(column).first } & statement.owner_columns).any?
      return fallback.call if defaults.any? { |value| unsupported_bind?(value) }

      binds = defaults + binds
      compiled = nil
      records = model.with_connection do |connection|
        compiled = @compiled.compute_if_absent([key, connection.prepared_statements, columns, extensions]) { compile(statement, connection, columns, extensions) }
        compiled && compiled.cache.execute(binds, connection)
      end
      return fallback.call unless compiled

      if owner
        proxy = owner.association(association)
        records.each do |record|
          proxy.set_inverse_instance_from_queries(record)
          proxy.set_strict_loading(record)
        end
      end
      records.each(&:strict_loading!) if compiled.strict_loading

      compiled.preload.each do |associations|
        Preload.call(records, associations, strict: compiled.strict_loading)
      end
      records.reverse! if statement.reverse
      result = statement.one ? records.first : records

      verify(key, result, fallback.call, compiled.preload) if VERIFY
      result
    end

    private

    # Whether `owner.association` reads like the statement says: a collection
    # whose key columns are the ones the statement compares, on the owner's
    # primary key, and no records of its own in memory (CollectionProxy reads a
    # loaded target, and merges unsaved records into one, instead of querying).
    def owner_chain?(owner, association, statement, model)
      owner_chain_failure(owner, association, statement, model).nil?
    end

    # Why `owner_chain?` is false (a Symbol), or nil.
    def owner_chain_failure(owner, association, statement, model)
      # A reader the owner's class redefines, or a double stubs (Mocha prepends an anonymous
      # module to the object's singleton class), answers something other than the association.
      return :reader_redefined if redefined?(owner, association)
      return :scope_redefined if scope_redefined?(model)

      proxy = owner.association(association)
      return :owner_new_record if owner.new_record?
      # A terminal on the proxy itself reads the target; links after the reader query.
      unless statement.relation
        return :target_loaded if proxy.loaded?
        return :target_unsaved if proxy.target.any?
      end

      shape = @owner_chains.compute_if_absent([owner.class, association, statement.owner_keys]) do
        reflection = owner.class._reflect_on_association(association)
        primary_key = reflection&.active_record_primary_key
        !!(reflection && reflection.collection? && !reflection.through_reflection? && reflection.klass.equal?(model) &&
           primary_key.is_a?(String) && primary_key == owner.class.primary_key &&
           (statement.owner_keys.nil? || statement.owner_keys == [reflection.foreign_key, reflection.type].compact.map(&:to_s)))
      end
      :reflection unless shape
    end

    # What `Model.all`'s default scopes add to a chain right now, for a
    # statement that is not rooted at `Model.unscoped`. A default scope is
    # Ruby that runs at query time (it may read request state, branch, or
    # return nil), so Rails evaluates it here, once per call, exactly as
    # `Model.all` would. The result is usable only when it is the model's
    # `unscoped` relation plus `where(column: value)` equality conditions on
    # its own table: then the statement is built over the same conditions
    # with the values as binds (see `compile`), and one statement serves
    # every value. `extending` only adds modules to the Relation object
    # (query_methods.rb `extending!`), so modules that are named constants (the
    # same ones at every call) are accepted too, and `compile` builds the
    # statement over a relation extended with them. Anything else (a condition
    # that is not equality, nil, a join, an order, an anonymous extension...)
    # is nil, and the caller runs Rails' chain. Returns `[columns, values,
    # extensions]`.
    def default_binds(model)
      return NO_DEFAULTS if model.default_scopes.empty? && !default_scope_method?(model)

      refused, skipped = @opaque[model] || [0, 0]
      if refused >= OPAQUE_LIMIT && skipped + 1 < OPAQUE_RETRY
        @opaque[model] = [refused, skipped + 1]
        return
      end

      shape = default_shape(model, model.send(:relation), model.default_scoped)
      if shape
        @opaque.delete(model)
      else
        @opaque[model] = [refused + 1, 0]
      end
      shape
    end

    # Scoping::Default::ClassMethods#build_default_scope also honors a
    # class that defines `default_scope` itself.
    def default_scope_method?(model)
      !ActiveRecord::Base.is_a?(model.method(:default_scope).owner)
    end

    def default_shape(model, base, scoped)
      return unless scoped.values.except(:where, :extending) == base.values.except(:where, :extending)

      extensions = scoped.extending_values
      return unless extensions.first(base.extending_values.size) == base.extending_values
      extensions = (extensions - base.extending_values).freeze
      return unless extensions.all? { |mod| extension?(mod) }

      before = base.where_clause.send(:predicates)
      predicates = scoped.where_clause.send(:predicates)
      return unless predicates.first(before.size) == before

      columns = []
      values = []
      predicates.drop(before.size).each do |node|
        condition = default_condition(model, node)
        return unless condition.is_a?(Array)

        columns << condition[0]
        values.concat(condition[1])
      end
      [columns.freeze, values, extensions]
    end

    # The longest list of an `IN` default condition that gets a statement of its own (the
    # length is part of the statement, so one statement per length).
    MAX_LIST = 8

    # One condition a default scope adds, as `[column, values]` or the name (a String) of
    # what is wrong with it. `column` is the attribute name for `where(column: value)`, else
    # `[name, :not_eq]`, `[name, :in, n]` or `[name, :notin, n]` (`where.not(column: value)`,
    # `where(column: [n values])`, `where.not(column: [n values])`), which `compile` builds
    # again over bind placeholders, the values being `values`.
    def default_condition(model, node)
      case node
      when Arel::Nodes::HomogeneousIn
        return "non_equality_homogeneousin" unless node.instance_of?(Arel::Nodes::HomogeneousIn)

        attribute = node.attribute
        return "attribute" unless attribute.is_a?(Arel::Attributes::Attribute) && attribute.relation == model.arel_table
        return "column" unless model.columns_hash.key?(attribute.name.to_s)

        list = node.values
        return "list_length" unless (2..MAX_LIST).cover?(list.size)
        return "list_value" if list.any? { |value| unsupported_bind?(value) }

        [[attribute.name.to_s, node.type, list.size].freeze, list]
      when Arel::Nodes::Equality, Arel::Nodes::NotEqual
        return "non_equality_#{node.class.name.split("::").last.downcase}" unless node.instance_of?(Arel::Nodes::Equality) || node.instance_of?(Arel::Nodes::NotEqual)

        attribute, bind = node.left, node.right
        # Predicate builder puts the QueryAttribute itself on the right (Arel
        # makes the bind of it when it compiles); a BindParam wraps one too.
        bind = bind.value if bind.is_a?(Arel::Nodes::BindParam)
        return "attribute" unless attribute.is_a?(Arel::Attributes::Attribute) && attribute.relation == model.arel_table
        return "bind_" + bind.class.name.to_s.split("::").last.downcase unless bind.is_a?(ActiveRecord::Relation::QueryAttribute)
        return "column" unless model.columns_hash.key?(attribute.name.to_s) && bind.name == attribute.name.to_s

        name = attribute.name.to_s
        [node.instance_of?(Arel::Nodes::Equality) ? name : [name, :not_eq].freeze, [bind.value]]
      else
        "non_equality_" + node.class.name.to_s.split("::").last.downcase
      end
    end

    # `scope` with one default condition added, over a bind placeholder for each value.
    def add_default_condition(scope, column, params)
      name, op, size = column
      case op
      when nil then scope.where(column => params.bind)
      when :not_eq then scope.where.not(name => params.bind)
      when :in then scope.where(name => Array.new(size) { params.bind })
      when :notin then scope.where.not(name => Array.new(size) { params.bind })
      end
    end

    # Whether a module `extending` adds is one every call adds again (a named
    # constant, not one made by a block) and leaves the loading of records to
    # Rails (see LOADING).
    def extension?(mod)
      @extensions.compute_if_absent([:default, mod]) do
        mod.is_a?(Module) && !mod.name.nil? && (overridden(mod) & LOADING).empty?
      end
    end

    # Whether `extending(mod)` in the chain itself adds methods only, none of
    # which a Relation already has: the statement does not run them.
    def plain_extension?(mod)
      @extensions.compute_if_absent([:chain, mod]) do
        mod.is_a?(Module) && !mod.name.nil? && overridden(mod).empty?
      end
    end

    # The instance methods of `mod` that are class methods of `model` too (a scope): a Relation
    # answers a scope by calling the class's, and an extended Relation answers with the module's
    # own method first.
    def scope_overrides(mod, model)
      (mod.instance_methods + mod.private_instance_methods).select { |name| model.respond_to?(name, true) }
    end

    # The instance methods of `mod` that ActiveRecord::Relation defines too.
    def overridden(mod)
      (mod.instance_methods + mod.private_instance_methods).select do |name|
        ActiveRecord::Relation.method_defined?(name) || ActiveRecord::Relation.private_method_defined?(name)
      end
    end

    # Build the Relation once and keep what loading it needs. `false` (not
    # nil, so compute_if_absent remembers it) when Rails would load it in a
    # way a StatementCache cannot reproduce. A chain that is not rooted at
    # `Model.unscoped` is built inside `relation.where(column: bind)....scoping` (`relation`, the
    # class's own plain Relation as `all` starts from, not `unscoped`, which a class may
    # redefine), so its `Model.all` is that relation: no default scope runs
    # and none is frozen into the statement. The default scopes' `extensions`
    # are applied to that relation, so a link of the chain that one of them
    # overrides behaves as it does on Rails' `Model.all`; but the statement
    # runs the chain once, so it is refused (`false`) when the chain called
    # such a link at all.
    def compile(statement, connection, columns, extensions)
      relation = nil
      overrides = []
      # Rails builds the relation over placeholders (StatementCache::Substitute) that stand for
      # values it would read keys, attributes or elements from; a condition that does that (a
      # composite association key, say) raises here, where the chain with real values may not.
      # Such a chain is Rails' to run, as one it cannot build is.
      cache = begin
        ActiveRecord::StatementCache.create(connection) do |params|
          relation = if statement.unscoped
            statement.build.call(params)
          else
            base = columns.inject(statement.model.send(:relation)) { |scope, column| add_default_condition(scope, column, params) }
            base = watch_overrides(base.extending(*extensions), extensions, overrides, statement.model) if extensions.any?
            base.scoping { statement.build.call(params) }
          end
        end
      rescue StandardError
        return false
      end
      return false if overrides.any?
      return false if relation.eager_loading? || relation.readonly_value
      return false unless builders_are_rails?(statement.model)
      return false unless (relation.extending_values - extensions).all? { |mod| plain_extension?(mod) }

      preload = relation.preload_values + relation.includes_values
      Compiled.new(cache: cache, preload: preload, strict_loading: relation.strict_loading_value)
    end

    # Relation methods a chain's links call. A statement is built once, so a link that something
    # redefined (a module prepended to ActiveRecord::Relation, one in the model's own relation
    # class) would run only then; the chain as written runs it on every call.
    BUILDERS = %i[where order limit preload includes joins left_joins left_outer_joins select group reorder lock
                  distinct reverse_order unscope ordered_relation].freeze

    # (Looked up on the model's Relation class, not the relation: an `extending` module a default
    # scope adds is the watcher's business, `watch_overrides`.)
    def builders_are_rails?(model)
      relation_class = model.relation_delegate_class(ActiveRecord::Relation)
      BUILDERS.all? { |name| rails_method?(relation_class.instance_method(name)) }
    end
    private :builders_are_rails?

    # `relation` with a module in front of its extensions that records which
    # of their Relation-overriding methods get called (and then calls them).
    # Extended on the object itself, not through `extending`, so it is not one
    # of the relation's extending_values; spawn/clone carry it along.
    def watch_overrides(relation, extensions, calls, model)
      names = extensions.flat_map { |mod| overridden(mod) + scope_overrides(mod, model) }.uniq
      return relation if names.empty?

      relation.extend(Module.new do
        names.each do |name|
          define_method(name) do |*args, &block|
            calls << name
            super(*args, &block)
          end
          ruby2_keywords(name)
        end
      end)
    end

    def verify(key, result, expected, preload)
      got = Array(result).map(&:id)
      want = Array(expected).map(&:id)
      raise "futamura #{key}: specialized #{got.inspect} != Rails #{want.inspect}" unless got == want
      preload.each do |spec|
        mine = Preload.signature(Array(result), spec)
        rails = Preload.signature(Array(expected), spec)
        raise "futamura #{key}: preloaded #{spec.inspect} differs from Rails" unless mine == rails
      end
    end
  end

  # One preload entry (one element of a Relation's preload_values or
  # includes_values), loaded the way ActiveRecord::Associations::Preloader
  # loads it, minus the work that does not depend on the request.
  #
  # The Preloader rebuilds, for every call, the branch tree, each
  # association's scope (the target's scope_for_association, the
  # polymorphic type condition, the reflection's own scope) and the loader
  # queries that group similar associations. For a given tree and owner
  # class none of that changes, so it is planned once here, and each call
  # runs only what Preloader::Association does per call: key the owners,
  # skip owners already loaded, load the missing keys with
  # `scope.where(key => keys)` (one query per group of loaders on a level
  # whose query is the same, as Preloader::Batch groups them), set inverses,
  # and assign targets.
  #
  # An entry is planned only when every association in its tree is one
  # whose scope can be built once: not `through:`, not a polymorphic
  # belongs_to, no composite key, no owner-dependent scope, a target with no
  # default_scope, and a scope that is either absent, defined by Active
  # Storage or Action Text, or certified static by Roundhouse
  # (`static_scopes`, from the app's own association declarations). Any
  # other entry is handed to Rails' Preloader whole.
  module Preload
    Node = Struct.new(:name, :reflection, :children, :spec)
    FRAMEWORK = %r{/(activestorage|actiontext)/}

    @plans = Concurrent::Map.new
    @scopes = Concurrent::Map.new
    @static_scopes = Set.new

    class << self
      # "Owner#association" names whose scope lambda Roundhouse found to
      # build a relation from literals only.
      def static_scopes(*names)
        @static_scopes.merge(names)
      end

      def call(records, spec, strict:)
        return if records.empty?

        root = records.first.class
        roots = @plans.compute_if_absent([spec, root]) { plan(spec, root) || false }
        if !roots || records.any? { |r| !r.instance_of?(root) } || scoped?(roots)
          return rails(records, spec, strict)
        end

        level = roots.map { |node| [node, records] }
        until level.empty?
          loaders = []
          level.each do |node, owners|
            next if owners.empty?
            if owners.all? { |o| o.class._reflect_on_association(node.name).equal?(node.reflection) }
              loaders << Loader.new(node, owners, scope_for(node.reflection, owners.first.class, strict))
            else
              # An STI subclass redeclared the association: Rails' own path.
              rails(owners, node.spec, strict)
            end
          end
          loaders.group_by(&:query_key).each_value { |similar| load_batch(similar) }
          loaders.each(&:run)
          level = loaders.flat_map { |l| l.node.children.map { |child| [child, l.preloaded_records] } }
        end
      end

      # Which associations a preload loaded, and to what, through the tree.
      def signature(records, spec)
        nodes(spec).map do |name, child|
          records.map do |record|
            association = record.association(name)
            targets = Array.wrap(association.target)
            [record.id, association.loaded?, targets.map(&:id), child ? signature(targets, child) : nil]
          end
        end
      end

      private

      def rails(records, spec, strict)
        scope = strict ? ActiveRecord::Relation::StrictLoadingScope : nil
        ActiveRecord::Associations::Preloader.new(records: records, associations: spec, scope: scope).call
      end

      # The children of a preload spec, exactly as Preloader::Branch reads them.
      def nodes(spec)
        Array.wrap(spec).flat_map { |a| Array(a).flat_map { |parent, child| [[parent.to_sym, child]] } }
      end

      def plan(spec, klass)
        nodes(spec).map do |name, child|
          reflection = klass._reflect_on_association(name)
          return nil unless plannable?(reflection)

          children = child ? plan(child, reflection.klass) : []
          return nil unless children

          Node.new(name, reflection, children, child ? { name => child } : name)
        end
      end

      def plannable?(reflection)
        return false unless reflection
        return false if reflection.options[:through] || reflection.polymorphic?
        return false if reflection.scope && reflection.scope.arity != 0
        return false if reflection.join_primary_key.is_a?(Array) || reflection.join_foreign_key.is_a?(Array)

        klass = reflection.klass
        return false if klass.abstract_class? || klass.default_scopes.any?

        reflection.scope.nil? ||
          FRAMEWORK.match?(scope_source(reflection.scope)) ||
          @static_scopes.include?("#{reflection.active_record.name}##{reflection.name}")
      end

      # Where a scope lambda was written. Rails' association builder wraps an
      # argument-less scope as `proc { instance_exec(&scope) }`, so look
      # through the wrapper to the lambda it closes over.
      def scope_source(scope)
        location = scope.source_location&.first.to_s
        if location.end_with?("associations/builder/association.rb") && scope.binding.local_variable_defined?(:scope)
          location = scope.binding.local_variable_get(:scope).source_location&.first.to_s
        end
        location
      end

      # A `Model.scoping { }` block changes scope_for_association, and so does a class that
      # redefines `unscoped` or `scope_for_association` (the plan builds the scope once).
      def scoped?(nodes)
        nodes.any? do |n|
          klass = n.reflection.klass
          klass.current_scope || Futamura.send(:scope_redefined?, klass) || scoped?(n.children)
        end
      end

      # Preloader::Association#build_scope, built once per association,
      # owner class and strictness.
      def scope_for(reflection, model, strict)
        @scopes.compute_if_absent([reflection, model, strict]) do
          klass = reflection.klass
          scope = klass.scope_for_association
          scope.where!(reflection.type => model.polymorphic_name) if reflection.type && !reflection.through_reflection?
          reflection_scope = reflection.join_scopes(klass.arel_table, klass.predicate_builder, klass).inject(klass.unscoped, &:merge!)
          scope.merge!(reflection_scope) unless reflection_scope.empty_scope?
          scope = scope.strict_loading if strict
          [scope, scope.values_for_queries]
        end
      end

      # Preloader::Association::LoaderRecords: keys of owners not yet
      # loaded, one query for the group, inverses set as records load.
      def load_batch(loaders)
        keys = Set.new
        already = {}
        loaders.each do |loader|
          loader.owners_by_key.each do |key, owners|
            if (loaded_owner = owners.find { |owner| loader.loaded?(owner) })
              already[key] = loader.target_for(loaded_owner)
            else
              keys << key
            end
          end
        end
        keys.subtract(already.keys)
        first = loaders.first
        loaded = if keys.empty?
          []
        else
          first.scope.where(first.association_key_name => keys).load { |record| loaders.each { |l| l.set_inverse(record) } }.to_a
        end
        raw = loaded + already.values.flatten
        loaders.each { |loader| loader.load_records(raw) }
      end
    end

    # Preloader::Association, for one planned association and its owners.
    class Loader
      attr_reader :node, :scope, :association_key_name, :query_key, :preloaded_records

      def initialize(node, owners, (scope, values))
        @node = node
        @reflection = node.reflection
        @klass = @reflection.klass
        @owners = owners.uniq(&:__id__)
        @scope = scope
        @association_key_name = @reflection.join_primary_key(@klass)
        @owner_key_name = @reflection.join_foreign_key
        @query_key = [@klass, @association_key_name, values]
        model = @owners.first.class
        @convert = @klass.type_for_attribute(@association_key_name).type != model.type_for_attribute(@owner_key_name).type
      end

      def owners_by_key
        @owners_by_key ||= @owners.each_with_object({}) do |owner, result|
          key = convert(owner._read_attribute(@owner_key_name))
          (result[key] ||= []) << owner if key
        end
      end

      def loaded?(owner)
        owner.association(@reflection.name).loaded?
      end

      def target_for(owner)
        Array.wrap(owner.association(@reflection.name).target)
      end

      def set_inverse(record)
        if (owners = owners_by_key[convert(record._read_attribute(@association_key_name))])
          owners.first.association(@reflection.name).set_inverse_instance(record)
        end
      end

      def load_records(raw_records)
        @records_by_owner = {}.compare_by_identity
        @preloaded_records = raw_records.select do |record|
          assigned = false
          owners_by_key[convert(record._read_attribute(@association_key_name))]&.each do |owner|
            entries = (@records_by_owner[owner] ||= [])
            if @reflection.collection? || entries.empty?
              entries << record
              assigned = true
            end
          end
          assigned
        end
      end

      def run
        @owners.each do |owner|
          next if loaded?(owner)

          association = owner.association(@reflection.name)
          records = @records_by_owner[owner] || []
          if @reflection.collection?
            association.target = records + association.target.reject(&:persisted?)
          else
            association.target = records.first
          end
        end
      end

      private

      def convert(key)
        @convert ? key.to_s : key
      end
    end
  end
end

# Opt-in measurement, off unless FUTAMURA_STATS names a directory. Each process
# writes futamura-stats-<pid>.json there at exit: per call site how many calls
# were specialized and how many fell back (and why), the time spent building
# statements, and the time each path took. FUTAMURA_STATS_AB=1 also runs the
# original chain after (or before, alternating) every specialized call and
# times it, so the two paths can be compared per site; like FUTAMURA_VERIFY it
# runs the chain twice, so it is for measuring, not for gating.
if ENV["FUTAMURA_STATS"].to_s != ""
  module Futamura
    module Stats
      DIR = ENV["FUTAMURA_STATS"]
      AB = ENV["FUTAMURA_STATS_AB"] == "1"
      Site = Struct.new(:calls, :specialized, :fallback, :specialized_s, :fallback_s, :guard_s, :ab_calls, :ab_spec_s, :ab_orig_s, keyword_init: true)

      @sites = {}
      @compiles = []
      @compile_reasons = {}
      @association_keys = [0, 0.0]
      @defined = []

      class << self
        attr_reader :sites, :compiles, :compile_reasons, :association_keys, :defined

        def now = Process.clock_gettime(Process::CLOCK_MONOTONIC)

        def site(key)
          @sites[key] ||= Site.new(calls: 0, specialized: 0, fallback: Hash.new(0), specialized_s: 0.0, fallback_s: 0.0,
                                   guard_s: 0.0, ab_calls: 0, ab_spec_s: 0.0, ab_orig_s: 0.0)
        end

        # Why the guards in Futamura.records sent a call to Rails' chain, in the order they are checked.
        # A guard that is none of the first three is named by what Futamura.records tests next, with
        # the model in brackets ("scoping_block[Shop]"); `model_unloaded` is a statement whose model
        # class was never resolved, which only a call refused before that (a bind) can leave behind.
        def reason(key, binds, root, owner = nil, association = nil)
          return "owner_not_record" if owner && !(ActiveRecord::Base === owner)

          binds = binds.call if Proc === binds
          # find_index, not find: the value that is refused is usually nil.
          index = binds.index { |value| Futamura.unsupported_bind?(value) }
          return "bind_#{kind(binds[index])}" if index

          statement = Futamura.instance_variable_get(:@statements).fetch(key)
          model = statement.model
          return "model_unloaded" unless model.is_a?(Class)
          return "root_not_model" if root && !root.equal?(model)
          redefined = statement.via && Futamura.send(:redefined_class_method, model, statement.via)
          return "class_method_redefined[#{model.name}.#{redefined}]" if redefined
          failure = owner && Futamura.send(:owner_chain_failure, owner, association, statement, model)
          return "owner_chain_#{failure}" if failure
          return @compile_reasons[key] if @compile_reasons[key]
          return "scoping_block[#{model.name}]" if !statement.unscoped && model.current_scope

          if !statement.unscoped && (model.default_scopes.any? || Futamura.send(:default_scope_method?, model))
            cause = default_shape_failure(model)
            opaque = ((Futamura.instance_variable_get(:@opaque)[model] || [0]).first >= Futamura::OPAQUE_LIMIT)
            return "default_scope_#{cause}#{opaque ? "_after_limit" : ""}[#{model.name}]"
          end

          "compiled_false[#{model.name}]"
        end

        # Futamura.default_shape's checks, in order, naming the first one that refuses (read only).
        def default_shape_failure(model)
          base = model.send(:relation)
          scoped = model.default_scoped
          return "values" unless scoped.values.except(:where, :extending) == base.values.except(:where, :extending)
          return "extending" unless (scoped.extending_values - base.extending_values).all? { |mod| Futamura.send(:extension?, mod) }

          before = base.where_clause.send(:predicates)
          predicates = scoped.where_clause.send(:predicates)
          return "prefix" unless predicates.first(before.size) == before

          predicates.drop(before.size).each do |node|
            failure = Futamura.send(:default_condition, model, node)
            return failure if failure.is_a?(String)
          end
          "shape_ok"
        rescue => e
          "raises_#{e.class.name.to_s.split("::").last.downcase}"
        end

        def kind(value)
          case value
          when nil then "nil"
          when Array then "array"
          when Range then "range"
          when ActiveRecord::Base then "record"
          when Set then "set"
          else value.class.name.to_s.downcase
          end
        end

        def dump
          return if @sites.empty? && @defined.empty?

          rows = @sites.transform_values do |s|
            h = s.to_h
            h[:fallback] = s.fallback
            h
          end
          File.write(File.join(DIR, "futamura-stats-#{Process.pid}.json"), JSON.generate(
            pid: Process.pid, defined: @defined, sites: rows, compiles: @compiles,
            association_key: { calls: @association_keys[0], seconds: @association_keys[1] }
          ))
        end
      end

      module Instrument
        def define(key, *args, **opts, &build)
          Stats.defined << key
          super
        end

        def association_key(*)
          t = Stats.now
          super
        ensure
          Stats.association_keys[0] += 1
          Stats.association_keys[1] += Stats.now - t
        end

        def records(key, binds, owner: nil, association: nil, root: nil, &fallback)
          site = Stats.site(key)
          site.calls += 1
          fell = nil
          fell_s = 0.0
          timed_fallback = proc do
            fell = Stats.reason(key, binds, root, owner, association)
            t = Stats.now
            begin
              fallback.call
            ensure
              fell_s = Stats.now - t
            end
          end
          started = Stats.now
          first = !Stats.instance_variable_get(:@seen_keys).include?(key)
          Stats.instance_variable_get(:@seen_keys) << key
          orig_first = Stats::AB && site.calls.odd?
          if orig_first
            t = Stats.now
            fallback.call
            orig_s = Stats.now - t
            started = Stats.now
          end
          result = super(key, binds, owner: owner, association: association, root: root, &timed_fallback)
          total = Stats.now - started
          if fell
            site.fallback[fell] += 1
            site.fallback_s += fell_s
            site.guard_s += total - fell_s
          else
            site.specialized += 1
            site.specialized_s += total
            if Stats::AB && !first
              unless orig_first
                t = Stats.now
                fallback.call
                orig_s = Stats.now - t
              end
              site.ab_calls += 1
              site.ab_spec_s += total
              site.ab_orig_s += orig_s
            end
          end
          result
        end

        private

        # `*`: forwards whatever arguments compile takes (statement, connection, columns, extensions...).
        def compile(statement, connection, *)
          t = Stats.now
          result = super
          Stats.compiles << { model: statement.model.name, seconds: Stats.now - t, built: result ? true : false }
          unless result
            key = Futamura.instance_variable_get(:@statements).key(statement)
            Stats.compile_reasons[key] = "relation_needs_rails[#{statement.model.name}]"
          end
          result
        end
      end

      @seen_keys = Set.new
    end

    singleton_class.prepend(Stats::Instrument)
    at_exit { Stats.dump }
  end
end
